"""
    Find the index of an element in a list. The element can appear multiple times.
    input:  alist - a list
            element - objective element
    output: index of the element in the list
    """
def get_all_indices(element: Any, alist: Any) -> object {
    result = [];
    offset = -1;
    while True {
        try {
            offset = alist.index(element, (offset + 1));
        } except ValueError {
            return result;
        }
        result.append(offset);
    }
}

"""
    isSpace :: str -> bool

    Returns True for any Unicode space character, and the control characters
    \t, \n, \r, \f, \v.
    """
def isSpace(s: Any) -> object {
    return (s in " \t\n\r\f\v");
}

