"""
	Format a seconds value into a human-readable form
	"""
def format_seconds(s: Any) -> object {
    (years, s) = divmod(s, 31556952);
    (min, s) = divmod(s, 60);
    (h, min) = divmod(min, 60);
    (d, h) = divmod(h, 24);
    return ('%sy, %sd, %sh, %sm, %ss' % (years, d, h, min, s));
}

"""How many elements is ``pred(elm)`` true for?

    With the default predicate, this counts the number of true elements.

    >>> count_true([1, 2, 0, "A", ""])
    3
    >>> count_true([1, "A", 2], lambda x: isinstance(x, int))
    2

    This is equivalent to the ``itertools.quantify`` recipe, which I couldn't
    get to work.
    """
def count_true(seq: Any, pred: Any = lambda (x: Any) { x; }) -> object {
    ret = 0;
    for x in seq {
        if pred(x) {
            ret += 1;
        }
    }
    return ret;
}

